      "bearerAuth": []
    }
  ],
  "x-readme": {
    "explorer-enabled": false,
    "headers": [
      {
        "key": "dw-client-app-key",
        "value": "{{yourAppKey}}"
      }
    ]
  },
  "tags": [
    {
      "name": "Subscriptions"
    }
  ],
  "paths": {
    "/subscriptions": {
      "post": {
        "deprecated": true,
        "tags": [
          "Subscriptions"
        ],
        "summary": "Create Subscription",
        "description": "Creates a Subscription charge for a User's Linked Bank Account.\n\nThis API is now deprecated as the Subscriptions product is no longer supported.",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/SubscriptionRequest"
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Creating a Subscription for a User's Linked Bank Account was successful.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Subscription"
                }
              }
            }
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "bankAccountID": {
        "type": "string",
        "example": "bank_a4656e60-321e-425b-aa0d-a2e75c38885f",
        "description": "The unique DriveWealth identifier that identifies each linked bank account."
      },
      "accountID": {
        "type": "string",
        "example": "cc07f91b-7ee1-4868-b8fc-823c70a1b932.1407775317759",
        "description": "The user's unique account identifier."
      },
      "subscriptionID": {
        "type": "string",
        "example": "subscription_4451b62e-0e88-46ce-9eab-f0a54ccdc599",
        "description": "The unique identifier that identifies the user's subscription."
      },
      "SubscriptionRequest": {
        "type": "object",
        "required": [
          "accountID",
          "bankAccountID",
          "planID"
        ],
        "properties": {
          "accountID": {
            "$ref": "#/components/schemas/accountID"
          },
          "bankAccountID": {
            "$ref": "#/components/schemas/bankAccountID"
          },
          "planID": {
            "type": "string",
            "example": "plan_1d3e1630-9107-47c2-a9c4-6cca93821cb7",
            "description": "The unique identifier that identifies the plan schedule."
          }
        }
      },
      "Subscription": {
        "type": "object",
        "properties": {
          "subscriptionID": {
            "$ref": "#/components/schemas/subscriptionID"
          }
        }
      }
    },
    "securitySchemes": {
      "bearerAuth": {
        "type": "http",
        "scheme": "bearer",
        "bearerFormat": "JWT"
      }
    }
  }
}
